//! Repository tasks. `cargo run -p xtask -- protocol <bundle.json> <out.rs>`
//! generates `folo-protocol`'s types from the bundled JSON Schemas with
//! typify (RB-02 step 3). `scripts/contracts.py` runs it.

use std::process::ExitCode;

const HEADER: &str = "// Generated by `cargo run -p xtask -- protocol` from specs/generated/folo.schema.json\n\
// (scripts/contracts.py generate). Do not edit.\n\n";

fn generate(bundle: &str) -> Result<String, String> {
    let text = std::fs::read_to_string(bundle).map_err(|e| format!("{bundle}: {e}"))?;
    let schema: schemars::schema::RootSchema =
        serde_json::from_str(&text).map_err(|e| format!("{bundle}: {e}"))?;
    let settings = typify::TypeSpaceSettings::default()
        .with_struct_builder(false)
        .to_owned();
    let mut space = typify::TypeSpace::new(&settings);
    space
        .add_root_schema(schema)
        .map_err(|e| format!("typify: {e}"))?;
    let file: syn::File = syn::parse2(space.to_stream()).map_err(|e| format!("syn: {e}"))?;
    Ok(format!("{HEADER}{}", prettyplease::unparse(&file)))
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match args.as_slice() {
        [command, bundle, out] if command == "protocol" => match generate(bundle) {
            Ok(code) => match std::fs::write(out, code) {
                Ok(()) => ExitCode::SUCCESS,
                Err(e) => {
                    eprintln!("{out}: {e}");
                    ExitCode::FAILURE
                }
            },
            Err(e) => {
                eprintln!("{e}");
                ExitCode::FAILURE
            }
        },
        _ => {
            eprintln!("Usage: cargo run -p xtask -- protocol <bundle.json> <out.rs>");
            ExitCode::from(2)
        }
    }
}
